use std::io

fn next_int() -> int {
    let line = io::read_line() ?? ""
    let t = line.trim()
    t.parse::<int>() ?? 0
}

fn main() {
    let limit = 200000
    let mut sieve: Vec<bool> = Vec::new()
    let mut count: Vec<int> = Vec::new()
    let mut largest: Vec<int> = Vec::new()
    let mut i = 0
    while i <= limit {
        sieve.push(true)
        count.push(0)
        largest.push(0)
        i += 1
    }
    sieve[0] = false
    sieve[1] = false
    i = 2
    while i * i <= limit {
        if sieve[i] {
            let mut j = i * i
            while j <= limit {
                sieve[j] = false
                j += i
            }
        }
        i += 1
    }
    let mut c = 0
    let mut last = 0
    i = 0
    while i <= limit {
        if sieve[i] {
            c += 1
            last = i
        }
        count[i] = c
        largest[i] = last
        i += 1
    }
    let t = next_int()
    let mut k = 0
    while k < t {
        let n = next_int()
        if n < 2 {
            println("0 none")
        } else {
            println("${count[n]} ${largest[n]}")
        }
        k += 1
    }
}

